widgets_values:
{
  "整体风格": "3D CG动漫，古代东方乡村质感，北宋初年江南乡野粗粝写实质感，午后暖金色日光与傍晚橘黄油灯交织，土木肌理粗粝可见，绸缎与粗布质感对比强烈，空气里浮着尘土与炊烟微粒",
  "角色档案": [
    "韩立，男，十岁，肤色黝黑身形瘦小，一头黑发扎成松散小髻，穿灰褐粗布短褐打着几块补丁，腰系麻绳，脚蹬一双旧草鞋",
    "韩胖子，男，四十岁上下，白白胖胖的圆脸蓄一撮小胡子，穿崭新墨青缎面长衫缀银扣，头戴瓜皮帽，脚蹬厚底皂靴，腰系一只绣银钱袋",
    "王护法，男，四十余岁，面庞瘦削颧骨高耸面皮微蜡，眼神锐利眼尾带刀疤，穿玄色紧身劲装外罩灰黑短披风，腰佩一柄黑鞘钢刀刀柄缠暗红绳，脚蹬黑色薄底快靴，手背青筋凸起",
    "张二，男，四十余岁，面皮粗糙眼角褶皱深刻，头戴破旧毡帽压着眉，穿洗得发灰的土布门丁号衣，腰系旧布带别着一根枣木梆子，脚蹬露趾草鞋，手指关节粗大",
    "酒楼熟客，男，三十余岁，满脸横肉下巴留着稀疏短须，穿洗得发白的赭色粗布短打露着多毛的小臂，臂上有淡色旧刀疤，脚蹬沾满油污的黑布鞋",
    "送饭小厮，男，十五六岁，面黄肌瘦两颊凹陷，头顶梳着两个歪斜总角，穿洗得发灰的青色短打，腰系沾着油渍的白围裙，脚蹬露趾草鞋"
  ],
  "道具档案": [
    "玄字三角黑旗，黑绸为底边缘滚着一寸宽朱红边，旗面正中用银线绣着一个笔力遒劲的玄字，丝线在暗光下泛着冷金属光泽，插在黑漆马车边框铜套内，风吹时猎猎作响",
    "沉甸甸的钱袋，藏青粗布缝制巴掌大小，袋口用同色麻绳抽紧打着死结，布面被内里银锭撑得鼓囊囊棱角分明，掂在手里有沉甸甸的坠手感，粗布纹理里渗着久用的油光"
  ],
  "场景档案": [
    "青牛镇镇口，正午暖金色日光从头顶斜洒下来，脚下是被车轮碾出深辙的黄土路，路两侧生着半人高的枯黄野草，两根歪歪斜斜的木柱架着一块掉漆木牌坊，牌坊上青牛镇三个字剥落大半，远处低矮土房连绵成片，灰褐屋顶上浮着几缕淡青色炊烟，更远处是黛色浅山轮廓",
    "青牛街，午后日光从街东侧屋檐斜切下来在青石板路上投下长长阴影，脚下是被岁月磨得发亮的青石板主街东西延伸，两侧是低矮砖木结构店铺，灰瓦土墙木窗棂，布幌子在风里半垂，街西端可见青牛客栈的斑驳木招牌，街面散落着几片干菜叶和马粪",
    "春香酒楼大堂，午饭时分暖黄光从木格窗棂透进来混着油灯暖光，脚下是踩得发黏的青石板地面，十几张发黑木桌条凳坐满食客，柜台上堆着酒坛摞着粗陶碗，东墙挂着褪色字画，柱子上漆皮剥落，空气里飘着酒菜热气和汗味，柜台后酒架上排着一排暗褐色酒坛",
    "春香酒楼后院厢房，午后偏西阳光从土墙头斜照进小院，脚下是青砖铺地缝隙长着青苔，院内一棵半枯老槐树投下斑驳树影，正北一间青砖厢房木门半掩，窗棂糊着发黄窗纸，屋里一张旧木床铺着灰布褥子，墙角一张瘸腿木桌，桌上放着粗陶茶壶",
    "春香酒楼门口夜，初夜色如墨蓝，酒楼门口两盏红纸灯笼被风拂得轻轻摇晃，橘黄灯光在青石板上投下暖红光团，门内透出喧闹人声和酒菜热气，街两侧店铺已上了门板，远处几声狗吠，黑漆马车停在门口灯下，铜饰件反光"
  ],
  "分镜序列": [
    {
      "编号": 1,
      "标题": "青牛镇-镇口远望",
      "时间段": [
        "0-5s，大全景缓慢降镜。正午暖金色日光斜照，远景黛色浅山绵延，中景灰褐土房连绵成低矮镇子轮廓，近景黄土路车辙深深，歪木牌坊掉漆的青牛镇三字在阳光下泛着白，空气中浮尘被照成金色微粒，音效：远处鸡鸣，风卷尘土的沙沙声",
        "5-10s，微移切中景。暖光从侧后方打在张二背上，张二斜靠在镇口牌坊木柱上，破毡帽压着半张脸，嘴里叼着一根狗尾草，手里枣木梆子垂在腿边，眼神慵懒地望向镇内街道，嘴角撇着一丝见多识广的不屑，音效：张二鼻子里轻哼一声，远处马蹄声隐约",
        "10-14s，焦点转移从张二侧脸转向镇西土路。暖金色逆光里，西边黄土路上扬起一团昏黄尘土，一辆青布篷马车轮廓在尘土里若隐若现，张二叼着狗尾草并未直起身，只是眼皮微抬，音效：马车轱辘碾过土路的咕噜声，马蹄哒哒声由远及近"
      ]
    },
    {
      "编号": 2,
      "标题": "青牛街-马车疾驰",
      "时间段": [
        "0-4s，跟随镜头马车后方跟拍。午后侧光，青布篷马车从镇口驶入青牛街，两匹灰骡马四蹄翻飞扬起尘土，车轮碾过青石板发出咯噔咯噔声响，街道两侧店铺布幌子被马车带起的风吹得向后飘，街上行人纷纷侧身避让，音效：马蹄哒哒急响，车轴吱呀声，行人避让的轻呼",
        "4-8s，固定机位全景。马车飞快驶过青牛客栈斑驳木招牌前，招牌上客栈二字被尘土糊住一半，马车丝毫未停继续向东疾驰，车篷布帘被风掀起一角又落下，看不清车内人影，青牛客栈门口伙计探出头来看了一眼又缩回去，音效：车帘啪啪拍打声，客栈门口伙计的嘀咕声",
        "8-13s，极缓推中景。马车一路飞驰到镇子东端春香酒楼门前才勒住缰绳，灰骡马打着响鼻刨动前蹄，马车辕木上拴着的铜铃叮当作响，春香酒楼陈旧木招牌在风里晃了晃，门里飘出酒菜白色热气，音效：骡马响鼻声，铜铃叮铃，缰绳勒紧的咯吱声"
      ]
    },
    {
      "编号": 3,
      "标题": "春香酒楼大堂-下车入内",
      "时间段": [
        "0-5s，从门外向内跟拍。暖黄灯光混着酒菜热气扑面而来，韩胖子先从马车辕上跳下来，腆着肚子用袖子擦了擦额头油汗，转身伸手把车上的韩立搀下来，韩立脚一沾地险些趔趄被韩胖子一把扶住手臂，韩立黝黑小脸上满是疲惫，旧草鞋上沾满黄土，音效：韩胖子靴子落地声，韩立草鞋蹭地声，酒楼内喧闹人声涌出",
        "5-10s，中景双人构图跟随。暖油灯侧光，韩胖子大摇大摆走在前面，韩立瘦小身形紧紧跟在韩胖子身侧半步后，灰褐短褐补丁在人群里格外显眼，韩胖子熟稔地和几张桌上的熟客点头拱手，穿过满座食客往酒楼内里走，周围食客投来好奇目光，音效：杯盏碰撞声，食客划拳声，韩胖子拱手时的寒暄声",
        "10-15s，过肩镜头从韩立肩后拍向食客桌。赭色短打酒楼熟客坐在靠门桌边，端着粗陶酒碗，看见韩胖子进来眼睛一亮，胳膊肘捅了捅旁边同伴，满脸横肉挤出戏谑笑容，眼睛在韩立黑瘦脸上和韩胖子圆脸上来回打量，酒碗停在半空，酒楼熟客说：\"老韩，这个黑小子长的和你很像，不会是你背着家里婆娘生的儿子吧\"（口音：本地乡音，语速：正常偏快，情绪：戏谑起哄），音效：酒碗放桌的咚声，旁边食客哄笑声起"
      ]
    },
    {
      "编号": 4,
      "标题": "春香酒楼大堂-得意认侄",
      "时间段": [
        "0-5s，微移中景双人。哄笑声中韩胖子不但没恼，反而腆着肚子得意地笑起来，圆脸上小胡子一抖一抖，他伸手亲昵地拍了拍韩立后脑勺，铜算盘坠随着笑声晃动，韩胖子说：\"呸！这是我本家带来的亲侄子，当然和我有几分像了\"（口音：东北腔混江湖油滑调，语速：正常，情绪：得意佯怒），音效：韩胖子拍后脑勺的轻啪声，食客们更大的笑声",
        "5-10s，近景聚焦韩立。暖黄灯光打在韩立黝黑小脸上，韩立被拍得缩了缩脖子，黑亮眼睛怯生生扫了一圈哄笑的食客，又迅速低下头盯着自己草鞋尖，小手不自觉攥紧了短褐衣角，裸露的小腿微微往后缩了半步，音效：韩立细微的呼吸声，食客笑声渐弱，杯盏重又碰撞声起"
      ]
    },
    {
      "编号": 5,
      "标题": "春香酒楼后院厢房-安顿休息",
      "时间段": [
        "0-5s，跟随中景从酒楼后门穿出。午后偏西阳光暖金色，韩胖子领着韩立穿过酒楼后厨油乎乎的过道，掀开后院蓝布门帘，光线陡然从昏黄变成明亮，一墙之隔外面竟是个偏僻安静小院，青砖地缝里长着青苔，老槐树影斑驳，韩立被阳光晃得眯了眯眼，音效：门帘掀动哗啦声，后厨锅铲声渐远，院外蝉鸣传入",
        "5-11s，双人中景。韩胖子走到正北厢房前推开吱呀作响的木门，一股旧木头和灰尘的味道散出来，韩胖子抬手指着厢房内那张旧木床，灰布褥子叠得整整齐齐放在床头，他脸上惯常的油滑笑容收了几分，换上和蔼神色低头看着身边瘦小的韩立，阳光从窗纸透进在地面投下方格光影，音效：木门吱呀声，院里老槐树叶沙沙声",
        "11-15s，近景韩胖子。暖侧光打在韩胖子圆脸上，他胖手按在韩立肩膀上轻轻拍了拍，神色认真温和，韩胖子说：\"小立，你在这屋里好好休息下，养好精神，等内门的管事一来，我就叫你过去，我要先出去一下，招呼几位熟客\"（口音：东北腔，语速：缓，情绪：和蔼叮嘱），音效：韩胖子手掌拍粗布的闷声，远处酒楼隐约喧闹"
      ]
    },
    {
      "编号": 6,
      "标题": "春香酒楼后院厢房-连声嘱咐",
      "时间段": [
        "0-5s，中景跟随。韩胖子说完转身匆匆往外走，藏青绸缎袍角扫过青砖地上的青苔，走到院门口蓝布门帘前时脚步突然顿住，他似乎不放心又转回身，圆脸上闪过一丝担忧，看见韩立还乖乖站在厢房门口望着他，韩胖子抬手指了指韩立又指了指院子地面，韩胖子说：\"别乱跑啊，镇子里人太多，别走丢了，最好别出院子\"（口音：东北腔，语速：正常，情绪：不放心嘱咐），音效：韩胖子靴子踩青砖声，门帘被风掀动的哗啦声",
        "5-9s，近景双人隔院对望。暖金色阳光斜照在两人之间青砖地上，韩立在厢房门口用力点了点头，松散小髻上碎发晃了晃，黑亮眼睛里没有怕生的怯意只有赶路后的疲惫，他看着院门口韩胖子的方向，嘴唇动了动，嗓子因为三天赶路有些沙哑，韩立说：\"恩！\"（口音：东北腔，语速：缓，情绪：乖巧顺从），音效：韩立沙哑的应声，韩胖子这才放心转身掀开布帘走出去，袍角消失在门帘后"
      ]
    },
    {
      "编号": 7,
      "标题": "春香酒楼后院厢房-和衣而眠",
      "时间段": [
        "0-5s，极缓推从门口向屋内。午后阳光从糊着黄纸的窗棂斜切进来，在青砖地面投下明暗方格，韩立看着韩胖子走出门帘消失，转过身打量这间小屋，瘸腿木桌上粗陶茶壶落着薄尘，旧木床灰布褥子看起来还算干净，他瘦小的身形在空旷屋里显得更小，音效：院外蝉鸣嘶嘶，远处酒楼隐约喧闹，韩立草鞋蹭青砖的沙沙声",
        "5-11s，中近景床边。韩立走到旧木床边，连草鞋都没脱，浑身像散了架一样一头栽倒在灰布褥子上，补丁摞补丁的短褐蹭起褥子上一点灰尘在光柱里浮动，他脑袋一沾枕头眼睛立刻就闭上了，黑瘦脸颊贴在粗糙灰布上，嘴唇微微张开呼吸均匀，松散小髻被压得变形，几缕碎发贴在汗湿的额角，音效：身体扑倒床铺的闷响，灰尘被惊起的细微声，韩立均匀的鼾声立刻响起"
      ]
    },
    {
      "编号": 8,
      "标题": "春香酒楼后院厢房-初晚饭叙",
      "时间段": [
        "0-5s，环境空镜转中景室内。傍晚橘黄油灯光从窗纸透出来，天色已经暗成墨蓝，老槐树影子在窗纸上张牙舞爪，送饭小厮弓着腰端着木托盘走到厢房门前，推开门把饭菜放在瘸腿木桌上，橘黄油灯火苗被开门带起的风吹得晃了晃，韩立已经醒了坐在床边，头发睡得更乱，音效：暮色里远处几声狗吠，小厮草鞋踩青苔的滑溜声，碗碟放桌声，油灯火苗噼啪",
        "5-10s，中景双人。韩胖子不慌不忙从门外走进来，藏青绸缎袍子上沾着点酒渍，脸上带着酒后红润，他反手带上门在瘸腿木桌旁坐下，看着韩立端碗大口扒饭的样子笑了笑，小胡子翘起来，他伸手给韩立倒了一碗粗茶，茶水在粗陶碗里晃荡，韩胖子说：\"怎么样，饭菜还合你胃口吧，有些想家了吧？\"（口音：东北腔，语速：正常，情绪：温和家常），音效：韩胖子进门脚步声，茶水倾倒声，椅腿拖动声，韩立咀嚼声",
        "10-15s，近景韩立。油灯暖光把韩立影子投在后面土墙上晃了晃，韩立放下饭碗，用袖子抹了抹嘴，黑亮眼睛在灯火下闪了闪，露出这个年纪少有的乖巧神色，他点了点头，手指无意识捻着短褐上的补丁边缘，韩立说：\"恩，有点想了\"（口音：东北腔，语速：缓，情绪：乖巧略带想家），音效：韩立放碗声，袖子擦嘴声，院外虫鸣唧唧"
      ]
    },
    {
      "编号": 9,
      "标题": "春香酒楼后院厢房-闲话江湖",
